import{_ as e,o,c as t,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Acerca de","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/about.md","filePath":"es-ES/user-guide/settings/about.md","lastUpdated":1786082398000}'),r={name:"es-ES/user-guide/settings/about.md"};function i(n,a,c,l,d,u){return o(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="acerca-de" tabindex="-1">Acerca de <a class="header-anchor" href="#acerca-de" aria-label="Permalink to &quot;Acerca de&quot;">​</a></h1><p>Muestra los números de versión de los componentes App, Core, Service y CLI (con color según si el servicio está sano en ese momento), una breve descripción de Lertaro, y enlaces a la página de inicio del proyecto y a la guía de usuario en línea.</p><h2 id="carpetas-de-datos" tabindex="-1">Carpetas de datos <a class="header-anchor" href="#carpetas-de-datos" aria-label="Permalink to &quot;Carpetas de datos&quot;">​</a></h2><p>Dos enlaces más, justo debajo de esos, abren las carpetas desde las que Lertaro lee y en las que escribe su propia configuración — cada uno muestra la ruta real como texto del enlace pulsable, creando primero la carpeta si aún no existe:</p><ul><li><strong>Carpeta de datos de usuario</strong> — la carpeta por usuario que contiene <code>user-settings.json</code>. Cada vez que se guarda la configuración, el archivo anterior se rota a <code>user-settings.json.bak.1</code> (desplazando hacia abajo cualquier copia de seguridad más antigua, hasta <code>.bak.5</code>) antes de escribir el nuevo, de modo que una edición defectuosa o un fallo a mitad de guardado siempre deja una copia reciente desde la que restaurar. También contiene el historial, certificados y cachés específicos del usuario.</li><li><strong>Carpeta de datos del equipo</strong> — la carpeta de todo el equipo usada por el servicio en segundo plano (<code>machine-settings.json</code>, cachés del índice de unidades locales y registros del servicio).</li></ul><p>La versión instalada usa <code>%LocalAppData%\\Lertaro</code> y <code>%ProgramData%\\Lertaro</code>. La versión portátil usa <code>Data\\Users\\&lt;SID hash&gt;</code> y <code>Data\\Machine</code> junto a la aplicación; si la carpeta portátil <code>Data</code> aún no se ha creado, reutiliza los datos existentes de la instalación por compatibilidad. Consulta <a href="./../getting-started.html#datos-portátiles">Datos portátiles</a> para conocer la prioridad.</p><h2 id="buscar-actualizaciones" tabindex="-1">Buscar actualizaciones <a class="header-anchor" href="#buscar-actualizaciones" aria-label="Permalink to &quot;Buscar actualizaciones&quot;">​</a></h2><ul><li>Botón <strong>Buscar actualización</strong> — consulta si hay una versión más reciente; la propia etiqueta del botón refleja el progreso (&quot;Comprobando...&quot;, y luego &quot;actualizado&quot; o el número de la nueva versión encontrada).</li><li>Si una cuenta sin privilegios de administrador no puede detener el servicio en segundo plano para instalar una actualización en el sitio, un banner de aviso lo explica y te remite en su lugar a la página de descarga manual.</li><li>Una vez encontrada una nueva versión: <ul><li><strong>Actualización automática silenciosa</strong> — descarga e instala en segundo plano, mostrando una barra de progreso, y luego reinicia Lertaro automáticamente.</li><li><strong>Ir a la página de descarga</strong> — abre la página de la versión en GitHub en tu navegador para una instalación manual.</li></ul></li></ul><p>Esto es un reflejo de las casillas <strong>Buscar actualizaciones automáticamente</strong> / <strong>Actualización silenciosa automática</strong> en <a href="./general.html#sistema">General → Sistema</a> — esas controlan si esta comprobación ocurre automáticamente al iniciar; esta página te permite dispararla manualmente en cualquier momento.</p>',9)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
